import{_ as t,o as i,c as a,ae as s}from"./chunks/framework.B2ul6ABY.js";const u=JSON.parse('{"title":"Runtime","description":"","frontmatter":{},"headers":[],"relativePath":"design/runtime.md","filePath":"design/runtime.md"}'),n={name:"design/runtime.md"};function r(o,e,l,c,d,h){return i(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="runtime" tabindex="-1">Runtime <a class="header-anchor" href="#runtime" aria-label="Permalink to &quot;Runtime&quot;">​</a></h1><blockquote><p>Canonical design document consolidated from <code>docs/design/runtime.md</code> during Stage 22. Stage 23 will reconcile detailed source anchors where needed.</p></blockquote><p>The runtime is the non-LLM support software that drives agent dispatch, manages card state transitions, tracks processes, handles crashes, and provides the event bus. Agents do not control the runtime — the runtime controls agents.</p><hr><h2 id="startup-sequence" tabindex="-1">Startup Sequence <a class="header-anchor" href="#startup-sequence" aria-label="Permalink to &quot;Startup Sequence&quot;">​</a></h2><ol><li><p><strong>Discover project</strong>: Walk up from <code>cwd</code> looking for <code>.saivage/saivage.json</code>, or use <code>PROJECT_ROOT</code> / <code>SAIVAGE_ROOT</code> environment variables. Set both env vars for subprocess inheritance.</p></li><li><p><strong>Load configuration</strong>: Read <code>.saivage/saivage.json</code>, interpolate <code>\${ENV_VAR}</code> references, validate against the config schema (see <code>configuration.md</code>).</p></li><li><p><strong>Initialize model router</strong>: Create provider and account instances from config. Inject OAuth tokens for providers and accounts that use them. Discover or load each provider&#39;s model capabilities, order providers by priority, and initialize per-candidate health state for <code>provider/account/model</code> attempts.</p></li><li><p><strong>Initialize MCP runtime</strong>: Register built-in MCP services (plan, notes, filesystem, shell, git, process management). Start configured external MCP servers (see <code>configuration.md §MCP Servers</code>). Begin health monitoring of external servers.</p></li><li><p><strong>Single-instance guard</strong>: Check <code>.saivage/runtime/state.json</code> for a still-alive PID. If alive and recent (&lt; 14 days), abort with an error. Then acquire an exclusive runtime lock via <code>O_CREAT|O_EXCL</code> on <code>.saivage-work/tmp/runtime/runtime.lock</code>. This closes the TOCTOU gap between the PID check and the first state write. If the lock file exists but its PID is dead or its timestamp is stale (&gt; 14 days), the lock is removed and re-acquired.</p></li><li><p><strong>Crash recovery</strong>: Read old <code>.saivage/runtime/state.json</code>. If the previous process died mid-execution:</p></li></ol><ul><li>Sweep stale <code>.tmp</code> files from <code>.saivage-work/tmp/runtime/</code>.</li><li>Reset any <code>active</code> or <code>running</code> cards to <code>backlog</code>.</li><li>If a card has a completed result file but was not yet transitioned, mark it for archival by the planner.</li><li>Clean stale notes from previous runs.</li><li>Clean stale stash files older than 24 hours.</li><li>Reconcile orphan card-history entries whose sequence exceeds the persisted card version.</li></ul><ol start="7"><li><p><strong>Event bus</strong>: Create the in-process event bus for runtime event distribution.</p></li><li><p><strong>Write initial runtime state</strong>: Persist <code>.saivage/runtime/state.json</code> with <code>status: &quot;idle&quot;</code>, current PID, and timestamp.</p></li><li><p><strong>Start stuck-agent supervisor</strong>: If enabled, begin periodic stuck-agent detection (see §Stuck Agent Detection below).</p></li><li><p><strong>Consume shutdown handoff</strong>: If a previous shutdown left a handoff summary, queue it as a startup directive for the planner&#39;s first session.</p></li><li><p><strong>Start server</strong>: Bind the HTTP + WebSocket server (see <code>server-api.md</code>).</p></li><li><p><strong>Start Telegram bot</strong>: If configured, connect the Telegram bot and wire it to analyst chat sessions.</p></li><li><p><strong>Start runtime dispatcher</strong>: Begin dispatching ready card work and wrapping each agent invocation with recovery handling (see §Agent Invocation Recovery below).</p></li></ol><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S1[Discover project] --&gt; S2[Load config]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S2 --&gt; S3[Init model router + OAuth]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S3 --&gt; S4[Init MCP runtime + services]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S4 --&gt; S5[Single-instance guard + lock]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S5 --&gt; S6[Crash recovery]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S6 --&gt; S7[Event bus + initial state]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S7 --&gt; S8[Stuck-agent supervisor]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S8 --&gt; S9[Consume shutdown handoff]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S9 --&gt; S10[Start server + Telegram]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S10 --&gt; S11[Runtime dispatcher]</span></span></code></pre></div><hr><h2 id="canonical-runtime-control" tabindex="-1">Canonical runtime control <a class="header-anchor" href="#canonical-runtime-control" aria-label="Permalink to &quot;Canonical runtime control&quot;">​</a></h2><p>Runtime pause/resume/freeze controls are shared across surfaces.</p><p>Mutating runtime state must flow through canonical helpers rather than ad hoc writes:</p><ul><li><code>pauseRuntimeControl</code></li><li><code>resumeRuntimeControl</code></li><li>runtime freeze/resume-from-freeze helpers</li><li><code>src/utils/runtime-state.ts</code> for actual persisted state writes and the idle/<code>active_card_run</code> coherence guard</li></ul><p>Operational invariants:</p><ul><li>there should be no direct production writers of <code>.saivage/runtime/state.json</code> outside the runtime-state module and canonical runtime-control helpers.</li><li>idle runtime states with <code>current_card_id === null</code> cannot retain a non-terminal <code>active_card_run</code>; <code>src/utils/runtime-state.ts</code> rejects that shape in strict/test mode and self-heals historical production state, with regression coverage in <code>tests/utils/runtime-state-invariant.test.ts</code> and <code>tests/server/operator-api-contract-fixtures.test.ts</code>.</li></ul><p>Cross-surface parity means web UI, REST, CLI, analyst chat, and runtime internals should observe the same pause/freeze state and the same resume rules.</p><p>Generic resume is intentionally rejected from <code>frozen</code> and <code>error</code> states; operators must use <code>resume-from-freeze</code> for the frozen path.</p><hr><h2 id="notification-delivery-and-stale-work-protection" tabindex="-1">Notification delivery and stale-work protection <a class="header-anchor" href="#notification-delivery-and-stale-work-protection" aria-label="Permalink to &quot;Notification delivery and stale-work protection&quot;">​</a></h2><p>The runtime persists notifications on disk and delivers them to running sessions at the next safe point.</p><p>Sources in the current design:</p><ul><li>tracked card mutations</li><li>directive/escalation notes</li><li>runtime pause/resume/freeze/resume-from-freeze</li><li>process termination</li><li>supported config/provider changes</li></ul><p>Delivery behavior:</p><ol><li>notifications are queued per session and for operator surfaces;</li><li>immediately before the next model call, the agent adapter prepends a synthetic user-role message summarizing operator updates;</li><li>after a successful model call, the notification is marked delivered;</li><li>if the call fails, the notification remains pending and will be replayed (at-least-once delivery).</li></ol><p>Blocking behavior:</p><ul><li><code>block</code> severity notifications prevent executor/reviewer terminal results from being accepted until they are acknowledged;</li><li>if an agent tries to finish anyway, the runtime reinvokes it with a blocking-notification instruction;</li><li>a second silent attempt fails the dispatch instead of silently accepting stale work.</li></ul><hr><h2 id="model-router-resolution" tabindex="-1">Model Router Resolution <a class="header-anchor" href="#model-router-resolution" aria-label="Permalink to &quot;Model Router Resolution&quot;">​</a></h2><p>The router receives an agent role and resolves it into an ordered attempt chain. The chain is built from the role&#39;s configured model list, provider capabilities, provider priority, account priority, and current health state.</p><p>For each requested model:</p><ol><li>Find all providers that can serve the model.</li><li>Sort providers by priority, then skip providers whose candidate for that model is still in cooldown.</li><li>For each provider, sort eligible accounts by account priority, then skip accounts whose candidate for that model is still in cooldown.</li><li>Try each resulting <code>provider/account/model</code> candidate in order.</li></ol><p>If one provider or account fails, the router tries the next eligible provider or account for the same model. It moves to the next model only after every provider/account candidate for the current model is unavailable, failing, or in cooldown. Candidate failures use the same recovery-delay behavior as agent invocation recovery: failed candidates are not retried until their cooldown expires, and successful candidates clear their failure state.</p><hr><h2 id="graceful-shutdown" tabindex="-1">Graceful Shutdown <a class="header-anchor" href="#graceful-shutdown" aria-label="Permalink to &quot;Graceful Shutdown&quot;">​</a></h2><p>On <code>SIGINT</code> or <code>SIGTERM</code>:</p><ol><li><strong>Freeze runtime tracker</strong>: Prevent agent activity callbacks from racing the final state write.</li><li><strong>Write shutdown summary</strong>: Persist why the shutdown happened (reason, requester, runtime uptime, active agents, current card, plan state) so the next startup can hand off context to the planner.</li><li><strong>Stop stuck-agent supervisor</strong>.</li><li><strong>Shutdown MCP runtime</strong>: Stop external MCP servers, close connections.</li><li><strong>Clear event bus</strong>: Drain subscriptions.</li><li><strong>Write final runtime state</strong>: Set status to <code>idle</code>.</li><li><strong>Release runtime lock</strong>: Delete the lockfile.</li></ol><p>If the shutdown was requested explicitly (via the analyst or an external signal), a shutdown reason is persisted separately. On the next startup, the planner receives a handoff directive explaining what happened and why, so it can resume from the right context.</p><hr><h2 id="runtime-lock" tabindex="-1">Runtime Lock <a class="header-anchor" href="#runtime-lock" aria-label="Permalink to &quot;Runtime Lock&quot;">​</a></h2><p>The runtime lock prevents concurrent instances from corrupting project state.</p><ul><li><strong>Mechanism</strong>: <code>O_CREAT|O_EXCL</code> atomic file creation at <code>.saivage-work/tmp/runtime/runtime.lock</code>. Contains JSON with <code>{ pid, started_at }</code>.</li><li><strong>Stale detection</strong>: If the lockfile exists, check whether its PID is alive (<code>kill(pid, 0)</code>). If the PID is dead or the recorded <code>started_at</code> is older than 14 days, the lock is considered stale, removed, and re-acquired.</li><li><strong>Release</strong>: Lockfile is deleted on graceful shutdown and on fatal error handlers (<code>uncaughtException</code>, <code>unhandledRejection</code>).</li><li><strong>Manual override</strong>: If the lock is truly stuck, the user can delete <code>.saivage-work/tmp/runtime/runtime.lock</code> manually.</li></ul><hr><h2 id="runtime-loop" tabindex="-1">Runtime Loop <a class="header-anchor" href="#runtime-loop" aria-label="Permalink to &quot;Runtime Loop&quot;">​</a></h2><p>The runtime does not have a single event loop — it is driven by agent completion events:</p><ol><li>When a goal becomes <code>active</code>, invoke its planner for initial decomposition.</li><li>When the planner finishes, queue the created terminal cards / sub-goals based on <code>depends_on</code> and <code>priority</code>.</li><li>Pick the next ready card from the queue and invoke the executor.</li><li>When the executor finishes a card, check if more cards are ready. If yes, execute the next one. If all sibling cards have reached terminal states (<code>done</code>, <code>failed</code>, or <code>cancelled</code>), re-invoke the planner.</li><li>When the planner declares done, invoke the reviewer.</li><li>When the reviewer passes, mark the goal <code>done</code> and check the parent. When the reviewer fails, re-invoke the planner with the assessment.</li></ol><h3 id="dispatch-rules" tabindex="-1">Dispatch rules <a class="header-anchor" href="#dispatch-rules" aria-label="Permalink to &quot;Dispatch rules&quot;">​</a></h3><ul><li>Only one planner, executor, or reviewer runs at a time (besides the analyst).</li><li>The analyst is always available concurrently.</li><li>Global pause stops new dispatch but does not kill running processes.</li><li>Card order within a goal is determined by <code>depends_on</code> first, then <code>priority</code> (lower number = higher priority).</li></ul><hr><h2 id="agent-invocation-recovery" tabindex="-1">Agent Invocation Recovery <a class="header-anchor" href="#agent-invocation-recovery" aria-label="Permalink to &quot;Agent Invocation Recovery&quot;">​</a></h2><p>Planner, executor, and reviewer sessions are discrete invocations started by the runtime. Each invocation runs inside a recovery wrapper:</p><ol><li>Start the agent session for the current card and invocation reason.</li><li>If the agent returns a valid structured result, apply the result and continue the normal runtime loop.</li><li>If the agent exits without a valid result (failure, context exhaustion, max compactions reached, provider error, process abort): <ul><li>Persist the failure to the relevant card note or plan diary.</li><li>Publish a runtime event.</li><li>Wait a recovery delay (default: 60 seconds).</li><li>Restart the same invocation with a recovery directive telling the agent to re-read persisted state and continue from the last safe point.</li></ul></li><li>If the analyst explicitly requests a restart, cancel the current invocation, persist the user&#39;s reason, and restart immediately without delay.</li><li>On <code>SIGINT</code>/<code>SIGTERM</code>, cancel the active invocation, write shutdown handoff, and stop dispatching.</li></ol><p>Continuous improvement mode applies only to the depth-0 project planner when the project is otherwise idle. In that mode, once all current top-level goals are terminal and no user work is queued, the runtime may invoke the project planner with an improvement directive. This does not change ordinary goal planning: goal planners are still invoked only at the defined card lifecycle points.</p><hr><h2 id="stuck-agent-detection" tabindex="-1">Stuck Agent Detection <a class="header-anchor" href="#stuck-agent-detection" aria-label="Permalink to &quot;Stuck Agent Detection&quot;">​</a></h2><p>A background supervisor periodically checks whether any agent is stuck (making no progress):</p><ul><li><strong>Interval</strong>: Configurable, default 20 minutes.</li><li><strong>Method</strong>: Feed recent runtime logs to a lightweight LLM and ask for a structured verdict: <code>{ stuck, confidence, reason, evidence }</code>.</li><li><strong>Threshold</strong>: After N consecutive &quot;stuck&quot; verdicts (default: 3), the supervisor selects an abort target.</li><li><strong>Abort priority</strong>: Lower-level agents are aborted first (reviewer → executor → planner), so the planner can handle the failure and retry or escalate.</li><li><strong>Force cancel</strong>: If an aborted agent doesn&#39;t stop within 10 minutes, a second cancel signal is sent.</li><li><strong>Recovery</strong>: When the supervisor detects the system is no longer stuck, the consecutive counter resets.</li></ul><p>The supervisor only logs and acts on truly stuck situations. It does not interfere with long-running but progressing agents.</p><hr><h2 id="context-compaction" tabindex="-1">Context Compaction <a class="header-anchor" href="#context-compaction" aria-label="Permalink to &quot;Context Compaction&quot;">​</a></h2><p>When an agent&#39;s conversation approaches its model&#39;s context window limit, the runtime performs compaction:</p><ul><li><strong>Trigger</strong>: When estimated token count exceeds a configurable percentage of the context window (default: 80%).</li><li><strong>Method</strong>: Summarize the full conversation using a cheap LLM call, then replace the history with the summary plus a directive to re-read authoritative state from disk.</li><li><strong>Fallback</strong>: If summarization fails, keep only the most recent 20% of messages plus a truncation notice.</li><li><strong>Limit</strong>: Maximum compactions per agent session (default: 3). After the limit, the agent is terminated and the invocation recovery wrapper restarts it with fresh context.</li><li><strong>Timeout</strong>: Summarization calls have a generous timeout (default: 20 minutes) to handle large conversations.</li></ul><hr><h2 id="self-check" tabindex="-1">Self-Check <a class="header-anchor" href="#self-check" aria-label="Permalink to &quot;Self-Check&quot;">​</a></h2><p>Agents periodically perform self-assessment during long-running work:</p><ul><li><strong>Mechanism</strong>: Every N tool-call rounds (configurable per role), the runtime injects a progress-assessment prompt asking the agent to evaluate whether it is making progress.</li><li><strong>Default frequencies</strong>: Executor roles check every 15 rounds, planner every 30 rounds, analyst never (chat-driven).</li><li><strong>Purpose</strong>: Detect circular behavior, unnecessary repetition, or goal drift before the stuck-agent supervisor needs to intervene.</li></ul><hr><h2 id="event-bus" tabindex="-1">Event Bus <a class="header-anchor" href="#event-bus" aria-label="Permalink to &quot;Event Bus&quot;">​</a></h2><p>An in-process pub/sub system distributes runtime events to interested subscribers (chat agents, Telegram channels, web UI):</p><h3 id="event-types" tabindex="-1">Event types <a class="header-anchor" href="#event-types" aria-label="Permalink to &quot;Event types&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Event type</th><th>Severity</th><th>When</th></tr></thead><tbody><tr><td><code>goal_completed</code></td><td>info</td><td>A goal transitions to <code>done</code></td></tr><tr><td><code>goal_failed</code></td><td>error</td><td>A goal transitions to <code>failed</code></td></tr><tr><td><code>escalation</code></td><td>warning</td><td>A planner escalates to its parent</td></tr><tr><td><code>card_failed</code></td><td>warning</td><td>A terminal card fails</td></tr><tr><td><code>review_complete</code></td><td>info</td><td>A reviewer finishes assessment</td></tr><tr><td><code>plan_updated</code></td><td>info</td><td>The planner creates/modifies cards</td></tr><tr><td><code>dispatch_held_for_notification</code></td><td>warning</td><td>Blocking operator change prevented finalization</td></tr></tbody></table><h3 id="subscription-features" tabindex="-1">Subscription features <a class="header-anchor" href="#subscription-features" aria-label="Permalink to &quot;Subscription features&quot;">​</a></h3><ul><li><strong>Filtering</strong>: Subscribers specify minimum severity (<code>info</code>, <code>warning</code>, <code>error</code>) and/or allowed event types.</li><li><strong>Pause/resume</strong>: Subscriptions can be paused (e.g. when a Telegram user is offline). Events are buffered up to a configurable limit (default: 100). Oldest events are dropped when the buffer is full.</li><li><strong>Timeout</strong>: Event handlers have a delivery timeout (default: 5 seconds) to prevent slow handlers from blocking the bus.</li></ul><hr><h2 id="process-registry" tabindex="-1">Process Registry <a class="header-anchor" href="#process-registry" aria-label="Permalink to &quot;Process Registry&quot;">​</a></h2><p>The runtime maintains a registry of all external processes launched by executors:</p><ul><li>Each process is tracked by ID, card association, PID, start time, status, and output file paths.</li><li>Process output (stdout, stderr, combined log) is always written to files under <code>.saivage-work/processes/&lt;proc-id&gt;/</code>.</li><li>When the planner is re-invoked, the registry provides the list of still-running processes so the planner can decide to wait, kill, or ignore them.</li><li>The analyst can tail, kill, or inspect any process through its tools.</li><li>Canonical process termination enqueues a <code>process_state</code> notification for the owning session when applicable.</li></ul><hr><h2 id="runtime-state-persistence" tabindex="-1">Runtime State Persistence <a class="header-anchor" href="#runtime-state-persistence" aria-label="Permalink to &quot;Runtime State Persistence&quot;">​</a></h2><p>The runtime state file (<code>.saivage/runtime/state.json</code>) is updated on every significant state change:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">status</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:           </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">idle | running | paused | frozen | error</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">pid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:              </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">number</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">started_at</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:       </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ISO timestamp</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">updated_at</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:       </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ISO timestamp</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">current_card_id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:  </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">string | null</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">current_agent_session_id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">string | null</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">paused</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:           </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">boolean</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">paused_at</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:        </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ISO timestamp | null</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">queue</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:            </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">string[]</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">running_processes:string[]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">frozen_reason</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:    </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">string | null</span></span></code></pre></div><p>The runtime state file is the source of truth for crash recovery. It is written atomically (write to <code>.tmp</code>, then rename) to prevent corruption on crash.</p><hr><h2 id="stash" tabindex="-1">Stash <a class="header-anchor" href="#stash" aria-label="Permalink to &quot;Stash&quot;">​</a></h2><p>When a tool call produces output too large for the LLM context window, the result is <strong>stashed</strong> — saved to a temporary file and replaced with a reference. The agent can then selectively read portions of the stashed content via <code>read_stash(path, offset, length)</code>.</p><ul><li>Stash files are stored under <code>.saivage-work/tmp/stash/</code>.</li><li>Each file is named <code>&lt;tool_name&gt;_&lt;short_uuid&gt;.txt</code>.</li><li>Security: <code>read_stash</code> only allows reading from the stash directory (path traversal is rejected).</li><li>Cleanup: Stash files older than 24 hours are removed on startup.</li></ul>`,86)])])}const g=t(n,[["render",r]]);export{u as __pageData,g as default};
